#!/usr/bin/env bash\n\n# Test suite for nightly-apt-cleanup-helper\n# Uses a mock `apt-get` to avoid touching the real system.\n\nset -euo pipefail\n\n# Create a temporary directory for the mock binary\nTMPDIR=$(mktemp -d)\ncleanup() { rm -rf "$TMPDIR"; }\ntrap cleanup EXIT\n\n# Mock apt-get script\ncat > "$TMPDIR/apt-get" <<'MOCKAPT'\n#!/usr/bin/env bash\n# Mock apt-get for testing nightly-apt-cleanup-helper\n# It understands two invocations:\n#   apt-get -s autoremove   -> prints a simulated dry‑run list\n#   apt-get -y autoremove   -> prints a simulated removal output\n\nif [[ "$*" == "-s autoremove" ]]; then\n  cat <<EOF\nReading package lists...\nBuilding dependency tree...\nReading state information...\nThe following packages will be REMOVED:\n  old-package1 old-package2\n0 upgraded, 0 newly installed, 2 to remove and 0 not upgraded.\nEOF\nelif [[ "$*" == "-y autoremove" ]]; then\n  echo "Removing old-package1... Done."\n  echo "Removing old-package2... Done."\nelse\n  echo "Mock apt-get received unexpected arguments: $*" >&2\n  exit 1\nfi\nMOCKAPT\nchmod +x "$TMPDIR/apt-get"\n\n# Prepend mock directory to PATH so our script picks it up\nexport PATH="$TMPDIR:$PATH"\n# Tell the script we are in mock mode (optional flag)\nexport MOCK_APT=1\n\n# Source the utility script\nSCRIPT_PATH="$(dirname "${BASH_SOURCE[0]}")/../src/apt_cleanup.sh"\n\n# Helper to capture output\nrun_helper() {\n  bash "$SCRIPT_PATH" "$@"\n}\n\n# Test 1: Dry‑run (no -y) – should list packages and then abort\noutput=$(run_helper 2>&1 || true)\n# Expect the list line to contain both mock packages\nif ! echo "$output" | grep -q "old-package1 old-package2"; then\n  echo "[FAIL] Dry‑run did not list expected packages" >&2\n  exit 1\nfi\n# Since we did not auto‑confirm, the script should ask for confirmation and then abort\nif echo "$output" | grep -q "Proceed with removal"; then\n  echo "[PASS] Dry‑run prompts for confirmation as expected"\nelse\n  echo "[FAIL] Dry‑run missing confirmation prompt" >&2\n  exit 1\nfi\n\n# Test 2: Auto‑confirm with -y – should perform mock removal and report success\noutput=$(run_helper -y 2>&1)\n# Verify that mock removal messages appear\nif echo "$output" | grep -q "Removing old-package1... Done." && echo "$output" | grep -q "Removing old-package2... Done."; then\n  echo "[PASS] Auto‑confirm removal messages detected"\nelse\n  echo "[FAIL] Auto‑confirm removal messages missing" >&2\n  exit 1\nfi\n# Verify final success message\nif echo "$output" | grep -q "Debris cleared"; then\n  echo "[PASS] Success message present"\nelse\n  echo "[FAIL] Success message missing" >&2\n  exit 1\nfi\n\n# All tests passed\nexit 0\n
